exercises.solution:
def selesaikan_2x2(a, b, c, d, e, f):
    det = a * d - b * c
    if det == 0:
        return None
    x = (e * d - b * f) / det
    y = (a * f - e * c) / det
    return round(x, 6), round(y, 6)

