def jenis_solusi(A, b):
    (a, bb), (c, d) = A
    if a * d - bb * c != 0:
        return "tunggal"
    if a != 0:
        k = c / a
    else:
        k = d / bb
    return "tak hingga" if abs(k * b[0] - b[1]) < 1e-9 else "tidak ada"

