exercises.solution:
def r_kuadrat(y, prediksi):
    rata = sum(y) / len(y)
    sse = sum((a - b) ** 2 for a, b in zip(y, prediksi))
    sst = sum((a - rata) ** 2 for a in y)
    if sst == 0:
        return 1.0 if sse == 0 else 0.0
    return round(1 - sse / sst, 4)
